// A adapter une seule fois : ID du document Grist.
const userId = Number($input.first().json.query.userId);
return [{ json: { docId: 'cRP1WgZQv7KmwmVrUbuEF8', userId } }];

// Grist encode les colonnes de type liste (Attachments, RefList) sous la
// forme ["L", id1, id2, ...] : "L" est un marqueur, pas une valeur.
function refId(v) { return Array.isArray(v) ? v[1] : v; }
function firstAttachment(v) {
  if (!Array.isArray(v) || !v.length) return null;
  const ids = v[0] === 'L' ? v.slice(1) : v;
  return ids.length ? ids[0] : null;
}

const config = $('Set Config').first().json;
const pullsRows = $('Get Pulls').all().map((i) => i.json).filter((p) => p.id != null && refId(p.User) === config.userId);
const cardsRows = $('Get Cards').all().map((i) => i.json).filter((c) => c.id != null && c.Active);
const raritiesRows = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const extensionsRows = $('Get Extensions').all().map((i) => i.json).filter((r) => r.id != null);
const usersRows = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const pseudoById = {}; usersRows.forEach((u) => { pseudoById[u.id] = u.Pseudo; });

const extensionById = {};
extensionsRows.forEach((e) => { extensionById[e.id] = { id: e.id, name: e.Name, key: e.Key, sortOrder: e.SortOrder || 0 }; });

const rarityById = {};
raritiesRows.forEach((r) => {
  rarityById[r.id] = { id: r.id, name: r.Name, key: r.Key, colorHex: r.ColorHex, sortOrder: r.SortOrder || 0, disenchantValue: r.DisenchantValue || 0, craftCost: r.CraftCost || 0 };
});

const cards = cardsRows.map((c) => {
  const firstObtainedById = refId(c.FirstObtainedBy);
  return {
    cardId: c.id,
    name: c.Name,
    artist: c.Artist,
    description: c.Description || null,
    imageId: firstAttachment(c.Image),
    rarity: rarityById[refId(c.Rarity)] || null,
    extension: extensionById[refId(c.Extension)] || null,
    isPromo: !!c.IsPromo,
    firstObtainedBy: firstObtainedById ? (pseudoById[firstObtainedById] || null) : null,
    firstObtainedAt: c.FirstObtainedAt || null,
    maxSerial: c.MaxSerial || 100
  };
});

const ownedCounts = {};
const lastObtained = {};
const serialNumbers = {};
const copiesByCard = {};
for (const p of pullsRows) {
  const cardRef = refId(p.Card);
  ownedCounts[cardRef] = (ownedCounts[cardRef] || 0) + 1;
  if (!lastObtained[cardRef] || (p.ObtainedAt || 0) > lastObtained[cardRef]) {
    lastObtained[cardRef] = p.ObtainedAt || 0;
  }
  if (p.SerialNumber != null) {
    if (!serialNumbers[cardRef]) serialNumbers[cardRef] = [];
    serialNumbers[cardRef].push(p.SerialNumber);
  }
  // Chaque exemplaire individuel (pullId + son numero de serie) : necessaire
  // pour choisir PRECISEMENT quelle carte donner dans un echange (trade.js),
  // au-dela du simple compteur xN.
  if (!copiesByCard[cardRef]) copiesByCard[cardRef] = [];
  copiesByCard[cardRef].push({ pullId: p.id, serialNumber: p.SerialNumber != null ? p.SerialNumber : null });
}
const owned = Object.entries(ownedCounts).map(([cardId, count]) => ({
  cardId: Number(cardId),
  count,
  lastObtainedAt: lastObtained[cardId] || null,
  serialNumbers: (serialNumbers[cardId] || []).sort((a, b) => a - b),
  copies: (copiesByCard[cardId] || []).sort((a, b) => (a.serialNumber || 0) - (b.serialNumber || 0))
}));

const stats = { owned: owned.length, total: cards.length };

return [{ json: { cards, owned, stats } }];

